1	// Task-shaped wrappers over lib/llm. Each function asks the model for strict
2	// JSON and, if the key is missing or the call fails, returns a deterministic
3	// stand-in built from the same input so the app never hard-fails on AI.
4	
5	import { chatJSON, LLMError, llmConfigured } from "./llm";
6	import type { CompareAxis, ExportDraft, ExportFormat } from "./types";
7	
8	/** Coerce a model's field to a clean string[] no matter what it actually sent. */
9	function arr(v: unknown): string[] {
10	  if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
11	  if (typeof v === "string" && v.trim()) return [v.trim()];
12	  return [];
13	}
14	
15	function sentences(text: string): string[] {
16	  return text
17	    .replace(/\s+/g, " ")
18	    .split(/(?<=[。．.!?！？])\s*/)
19	    .map((s) => s.trim())
20	    .filter((s) => s.length > 1);
21	}
22	
23	// ── Source / memo summary ────────────────────────────────────
24	export type SourceDigest = {
25	  title?: string;
26	  summary: string[];
27	  points: string[];
28	  suggestedTags: string[];
29	};
30	
31	function fallbackDigest(text: string): SourceDigest {
32	  const s = sentences(text);
33	  return {
34	    summary: s.slice(0, 3),
35	    points: s.slice(0, 2),
36	    suggestedTags: [],
37	  };
38	}
39	
40	export async function summariseSource(input: {
41	  title?: string;
42	  text: string;
43	  kind: string;
44	}): Promise<SourceDigest> {
45	  const body = input.text.trim();
46	  if (!llmConfigured() || body.length < 40) return fallbackDigest(body);
47	  try {
48	    const out = await chatJSON<SourceDigest>([
49	      {
50	        role: "system",
51	        content:
52	          "あなたは読書メモの補助。与えられた本文を日本語で要約する。返答は JSON のみ: " +
53	          '{"title": string, "summary": string[3], "points": string[1..3], "suggestedTags": string[2..5]}. ' +
54	          "summary は各40字以内の要点。points は本文の主張。suggestedTags は短い名詞句。",
55	      },
56	      {
57	        role: "user",
58	        content: `種別: ${input.kind}\nタイトル: ${input.title ?? "(不明)"}\n\n本文:\n${body.slice(0, 8000)}`,
59	      },
60	    ]);
61	    return {
62	      title: typeof out.title === "string" ? out.title : input.title,
63	      summary: arr(out.summary).slice(0, 3),
64	      points: arr(out.points).slice(0, 3),
65	      suggestedTags: arr(out.suggestedTags).slice(0, 5),
66	    };
67	  } catch (e) {
68	    if (!(e instanceof LLMError)) throw e;
69	    return { ...fallbackDigest(body), title: input.title };
70	  }
71	}
