73	export async function summariseMemo(text: string): Promise<SourceDigest> {
74	  const body = text.trim();
75	  if (!llmConfigured() || body.length < 30) {
76	    const s = sentences(body);
77	    return {
78	      summary: s.length ? s.slice(0, 3) : ["（本文なし）"],
79	      points: s.slice(0, 2),
80	      suggestedTags: [],
81	    };
82	  }
83	  try {
84	    const out = await chatJSON<SourceDigest>([
85	      {
86	        role: "system",
87	        content:
88	          "ユーザーが書き殴ったメモを整える。返答は JSON のみ: " +
89	          '{"summary": string[1..3], "points": string[1..2], "suggestedTags": string[1..4]}. ' +
90	          "元の意図を変えず、要点を短く言い直す。",
91	      },
92	      { role: "user", content: body.slice(0, 4000) },
93	    ]);
94	    return {
95	      summary: arr(out.summary).slice(0, 3),
96	      points: arr(out.points).slice(0, 2),
97	      suggestedTags: arr(out.suggestedTags).slice(0, 4),
98	    };
99	  } catch (e) {
100	    if (!(e instanceof LLMError)) throw e;
101	    const s = sentences(body);
102	    return { summary: s.slice(0, 3), points: s.slice(0, 2), suggestedTags: [] };
103	  }
104	}
