106	// ── Compare board synthesis ──────────────────────────────────
107	export type CompareSynthesis = {
108	  axes: CompareAxis[];
109	  summary: string;
110	  candidateAxes: string[];
111	};
112	
113	export async function synthesiseCompare(
114	  sources: { title: string; summary: string[] }[]
115	): Promise<CompareSynthesis> {
116	  const names = sources.map((s) => s.title);
117	  if (!llmConfigured() || sources.length < 2) {
118	    return {
119	      axes: [{ name: "主題", values: sources.map((s) => s.summary[0] ?? null), accentCols: [] }],
120	      summary: llmConfigured()
121	        ? "比較には2本以上の出典が必要です。"
122	        : "差分の自動抽出には OPENROUTER_API_KEY が必要です。",
123	      candidateAxes: [],
124	    };
125	  }
126	  try {
127	    const out = await chatJSON<CompareSynthesis>([
128	      {
129	        role: "system",
130	        content:
131	          "複数の出典を表で比較する。返答は JSON のみ: " +
132	          '{"axes":[{"name":string,"values":(string|null)[],"accentCols":number[]}],' +
133	          '"summary":string,"candidateAxes":string[]}. ' +
134	          "values は sources と同じ順・同じ長さ。触れていない出典は null。" +
135	          "accentCols は出典どうしが食い違う列の index。axes は3〜5個。summary は分岐の理由を1〜2文で。",
136	      },
137	      {
138	        role: "user",
139	        content: JSON.stringify(
140	          { sources: sources.map((s, i) => ({ i, title: s.title, summary: s.summary })) },
141	          null,
142	          1
143	        ),
144	      },
145	    ]);
146	    const axes = (Array.isArray(out.axes) ? out.axes : [])
147	      .filter((a) => a?.name)
148	      .map((a) => ({
149	        name: a.name,
150	        values: names.map((_, i) => a.values?.[i] ?? null),
151	        accentCols: (Array.isArray(a.accentCols) ? a.accentCols : []).filter(
152	          (c) => typeof c === "number" && c >= 0 && c < names.length
153	        ),
154	      }));
155	    return {
156	      axes: axes.length
157	        ? axes
158	        : [{ name: "主題", values: sources.map((s) => s.summary[0] ?? null), accentCols: [] }],
159	      summary: out.summary ?? "",
160	      candidateAxes: arr(out.candidateAxes).slice(0, 4),
161	    };
162	  } catch (e) {
163	    if (!(e instanceof LLMError)) throw e;
164	    return {
165	      axes: [{ name: "主題", values: sources.map((s) => s.summary[0] ?? null), accentCols: [] }],
166	      summary: "差分のまとめに失敗しました（AI応答なし）。",
167	      candidateAxes: [],
168	    };
169	  }
170	}
