172	// ── Export draft ─────────────────────────────────────────────
173	export async function rewriteForExport(input: {
174	  title: string;
175	  /** The note body, already flattened to Markdown (see lib/note-delta.ts). */
176	  markdown: string;
177	  format: ExportFormat;
178	}): Promise<Pick<ExportDraft, "title" | "blocks" | "provenance" | "warning">> {
179	  const plain = input.markdown.trim();
180	
181	  const passthrough = {
182	    title: input.title,
183	    blocks: plain
184	      .split(/\n{2,}/)
185	      .map((para) => para.replace(/^\s*(#{1,6}|>|[-*]|\d+\.)\s+/, "").trim())
186	      .filter(Boolean)
187	      .map((text) => ({ type: "p" as const, text })),
188	    provenance: [
189	      { heading: "全体", from: `ノート「${input.title}」から`, tone: "accent" as const },
190	    ],
191	    warning: undefined,
192	  };
193	  if (!llmConfigured() || !plain) return passthrough;
194	
195	  const shape =
196	    input.format === "bullets"
197	      ? "箇条書き。blocks は {type:'h4'} 見出し1つと {type:'p'} 各項目（先頭に・）。"
198	      : input.format === "memo"
199	        ? "社内共有メモ。900字程度。blocks は {type:'p'} と {type:'h4'} の混在。"
200	        : "ブログ記事。1500〜2000字。blocks は {type:'p'} と {type:'h4'} の混在。";
201	  try {
202	    const out = await chatJSON<Pick<ExportDraft, "title" | "blocks" | "provenance" | "warning">>([
203	      {
204	        role: "system",
205	        content:
206	          `ノートを${input.format}形式に書き直す。${shape} ` +
207	          '返答は JSON のみ: {"title":string,"blocks":[{"type":"p"|"h4","text":string}],' +
208	          '"provenance":[{"heading":string,"from":string,"tone":"accent"|"muted"}],"warning":string|null}. ' +
209	          "事実を足さない。未確定部分は tone:'muted' で警告する。",
210	      },
211	      { role: "user", content: `現タイトル: ${input.title}\n\n本文:\n${plain.slice(0, 8000)}` },
212	    ]);
213	    const blocks = (Array.isArray(out.blocks) ? out.blocks : []).filter(
214	      (b) => b && (b.type === "p" || b.type === "h4") && b.text
215	    );
216	    return {
217	      title: out.title || input.title,
218	      blocks: blocks.length ? blocks : passthrough.blocks,
219	      provenance: (Array.isArray(out.provenance) ? out.provenance : passthrough.provenance).slice(
220	        0,
221	        4
222	      ),
223	      warning: out.warning || undefined,
224	    };
225	  } catch (e) {
226	    if (!(e instanceof LLMError)) throw e;
227	    return passthrough;
228	  }
229	}
