1	// Thin OpenRouter client. Every "AI" surface in the app (summaries, tag
2	// suggestions, the compare board, the export draft) goes through here.
3	// Configure it in .env.local:
4	//
5	//   OPENROUTER_API_KEY   — required for any AI output
6	//   OPENROUTER_MODEL_ID  — e.g. "mistralai/mistral-small-2603"
7	//   OPENROUTER_SITE_URL  — sent as HTTP-Referer (OpenRouter attribution)
8	//   OPENROUTER_APP_NAME  — sent as X-Title
9	//
10	// When the key is missing or a call fails, callers fall back to a small
11	// deterministic stand-in so the app keeps working offline.
12	
13	const ENDPOINT = "https://openrouter.ai/api/v1/chat/completions";
14	
15	export function llmConfigured(): boolean {
16	  return !!process.env.OPENROUTER_API_KEY;
17	}
18	
19	type Msg = { role: "system" | "user" | "assistant"; content: string };
20	
21	export class LLMError extends Error {}
22	
23	/** One chat completion. Throws LLMError on any non-success. */
24	export async function chat(
25	  messages: Msg[],
26	  opts: { json?: boolean; temperature?: number; maxTokens?: number } = {}
27	): Promise<string> {
28	  const key = process.env.OPENROUTER_API_KEY;
29	  if (!key) throw new LLMError("OPENROUTER_API_KEY is not set");
30	
31	  const ctrl = new AbortController();
32	  const timer = setTimeout(() => ctrl.abort(), 30_000);
33	  let res: Response;
34	  try {
35	    res = await fetch(ENDPOINT, {
36	      method: "POST",
37	      signal: ctrl.signal,
38	      headers: {
39	        "content-type": "application/json",
40	        authorization: `Bearer ${key}`,
41	        "HTTP-Referer": process.env.OPENROUTER_SITE_URL ?? "http://localhost:3000",
42	        "X-Title": process.env.OPENROUTER_APP_NAME ?? "Hazy",
43	      },
44	      body: JSON.stringify({
45	        model: process.env.OPENROUTER_MODEL_ID ?? "mistralai/mistral-small-2603",
46	        messages,
47	        temperature: opts.temperature ?? 0.4,
48	        max_tokens: opts.maxTokens ?? 1200,
49	        ...(opts.json ? { response_format: { type: "json_object" } } : {}),
50	      }),
51	    });
52	  } catch (e) {
53	    throw new LLMError(`request failed: ${(e as Error).message}`);
54	  } finally {
55	    clearTimeout(timer);
56	  }
57	
58	  if (!res.ok) {
59	    const body = await res.text().catch(() => "");
60	    throw new LLMError(`openrouter ${res.status}: ${body.slice(0, 300)}`);
61	  }
62	  const data = (await res.json()) as {
63	    choices?: { message?: { content?: string } }[];
64	  };
65	  const text = data.choices?.[0]?.message?.content?.trim();
66	  if (!text) throw new LLMError("empty completion");
67	  return text;
68	}
69	
70	/**
71	 * Chat completion parsed as JSON. Tolerates models that wrap the object in
72	 * prose or ```json fences. Throws LLMError if nothing parses.
73	 */
74	export async function chatJSON<T>(
75	  messages: Msg[],
76	  opts: { temperature?: number; maxTokens?: number } = {}
77	): Promise<T> {
78	  const raw = await chat(messages, { ...opts, json: true });
79	  const cleaned = raw
80	    .replace(/^```(?:json)?\s*/i, "")
81	    .replace(/\s*```$/, "")
82	    .trim();
83	  try {
84	    return JSON.parse(cleaned) as T;
85	  } catch {
86	    const start = cleaned.search(/[[{]/);
87	    const end = Math.max(cleaned.lastIndexOf("]"), cleaned.lastIndexOf("}"));
88	    if (start >= 0 && end > start) {
89	      try {
90	        return JSON.parse(cleaned.slice(start, end + 1)) as T;
91	      } catch {
92	        /* fall through */
93	      }
94	    }
95	    throw new LLMError(`could not parse JSON from: ${cleaned.slice(0, 300)}`);
96	  }
97	}
