1	// Helpers for the Quill note body (stored as `notes.body` — the bare Delta
2	// `ops` array). Pure functions, safe on the server (repo.ts) and the client.
3	
4	import type { DeltaOp } from "@repo/db";
5	import type { NoteSuggestion } from "./types";
6	
7	export type { DeltaOp };
8	
9	type Attrs = Record<string, unknown>;
10	
11	export function isDelta(v: unknown): v is DeltaOp[] {
12	  return (
13	    Array.isArray(v) &&
14	    v.every(
15	      (op) =>
16	        op != null &&
17	        typeof op === "object" &&
18	        ("insert" in op || "retain" in op || "delete" in op),
19	    )
20	  );
21	}
22	
23	/** Plain text of a Delta — every string insert concatenated, embeds dropped. */
24	export function deltaToPlainText(ops: DeltaOp[] | undefined | null): string {
25	  if (!Array.isArray(ops)) return "";
26	  let out = "";
27	  for (const op of ops) {
28	    if (typeof op.insert === "string") out += op.insert;
29	  }
30	  return out;
31	}
32	
33	/** One-line preview for the notes list. */
34	export function deltaExcerpt(ops: DeltaOp[] | undefined | null, max = 140): string {
35	  const s = deltaToPlainText(ops).replace(/\s+/g, " ").trim();
36	  return s.length > max ? `${s.slice(0, max)}…` : s || "…";
37	}
38	
39	/** Rough paragraph count (non-blank lines). */
40	export function paragraphCount(ops: DeltaOp[] | undefined | null): number {
41	  return deltaToPlainText(ops)
42	    .split(/\n+/)
43	    .filter((l) => l.trim()).length;
44	}
45	
46	function inlineMd(text: string, attrs: Attrs | undefined): string {
47	  if (!attrs) return text;
48	  let t = text;
49	  if (attrs.code) t = `\`${t}\``;
50	  if (attrs.bold) t = `**${t}**`;
51	  if (attrs.italic) t = `*${t}*`;
52	  if (typeof attrs.link === "string") t = `[${t}](${attrs.link})`;
53	  return t;
54	}
55	
56	function linePrefix(attrs: Attrs | undefined, ordinal: number): string {
57	  if (!attrs) return "";
58	  if (attrs.header === 2 || attrs.header === "2") return "## ";
59	  if (attrs.header === 3 || attrs.header === "3") return "### ";
60	  if (attrs.header === 1 || attrs.header === "1") return "# ";
61	  if (attrs.blockquote) return "> ";
62	  if (attrs.list === "ordered") return `${ordinal}. `;
63	  if (attrs.list === "bullet") return "- ";
64	  return "";
65	}
66	
67	/**
68	 * Delta → Markdown, limited to the formats the toolbar offers (bold, italic,
69	 * header 2/3, blockquote, bullet/ordered list, link). Used for export + as the
70	 * LLM's input in `rewriteForExport`.
71	 */
72	export function deltaToMarkdown(ops: DeltaOp[] | undefined | null): string {
73	  if (!Array.isArray(ops)) return "";
74	  const lines: string[] = [];
75	  let buf = "";
76	  let ordinal = 1;
77	
78	  for (const op of ops) {
79	    if (typeof op.insert !== "string") continue;
80	    const parts = op.insert.split("\n");
81	    for (let i = 0; i < parts.length; i++) {
82	      if (i > 0) {
83	        // `op.attributes` describes the line that just ended (the `\n`).
84	        const attrs = op.attributes as Attrs | undefined;
85	        const isOrdered = attrs?.list === "ordered";
86	        lines.push(linePrefix(attrs, ordinal) + buf);
87	        ordinal = isOrdered ? ordinal + 1 : 1;
88	        buf = "";
89	      }
90	      if (parts[i]) buf += inlineMd(parts[i], op.attributes as Attrs | undefined);
91	    }
92	  }
93	  if (buf) lines.push(buf);
94	
95	  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim();
96	}
97	
98	// ── legacy NoteBlock[] → Delta ──────────────────────────────
99	
100	const LINK_RE = /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g;
101	
102	/** `[t](u)` markdown in a legacy paragraph → inline link ops. */
103	function textToOps(text: string, extra?: Attrs): DeltaOp[] {
104	  const ops: DeltaOp[] = [];
105	  let last = 0;
106	  for (const m of text.matchAll(LINK_RE)) {
107	    const i = m.index ?? 0;
108	    if (i > last) ops.push({ insert: text.slice(last, i), ...(extra && { attributes: extra }) });
109	    ops.push({ insert: m[1], attributes: { ...extra, link: m[2] } });
110	    last = i + m[0].length;
111	  }
112	  if (last < text.length)
113	    ops.push({ insert: text.slice(last), ...(extra && { attributes: extra }) });
114	  return ops;
115	}
116	
117	type LegacyBlock =
118	  | { type: "p"; text: string; refs?: string }
119	  | { type: "quote"; text: string; cite: string; note?: string }
120	  | { type: "highlight"; before: string; mark: string; after: string }
121	  | { type: "suggestion"; kind: string; text: string; ref?: string };
122	
123	/**
124	 * One-time conversion of the old hand-rolled block model to a Quill Delta.
125	 * `suggestion` blocks are pulled out into the sidebar list.
126	 */
127	export function legacyBlocksToDelta(blocks: unknown): {
128	  body: DeltaOp[];
129	  suggestions: NoteSuggestion[];
130	} {
131	  const body: DeltaOp[] = [];
132	  const suggestions: NoteSuggestion[] = [];
133	  if (!Array.isArray(blocks)) return { body, suggestions };
134	
135	  for (const raw of blocks as LegacyBlock[]) {
136	    if (!raw || typeof raw !== "object") continue;
137	    if (raw.type === "p") {
138	      body.push(...textToOps(raw.text ?? ""));
139	      if (raw.refs) body.push({ insert: ` [${raw.refs}]` });
140	      body.push({ insert: "\n" });
141	    } else if (raw.type === "quote") {
142	      body.push(...textToOps(raw.text ?? ""));
143	      body.push({ insert: "\n", attributes: { blockquote: true } });
144	      const caption = [raw.cite, raw.note].filter(Boolean).join(" · ");
145	      if (caption) body.push({ insert: `— ${caption}` }, { insert: "\n" });
146	    } else if (raw.type === "highlight") {
147	      if (raw.before) body.push({ insert: raw.before });
148	      if (raw.mark) body.push({ insert: raw.mark, attributes: { background: "#423a6a" } });
149	      if (raw.after) body.push({ insert: raw.after });
150	      body.push({ insert: "\n" });
151	    } else if (raw.type === "suggestion") {
152	      suggestions.push({
153	        id: crypto.randomUUID(),
154	        kind: raw.kind ?? "AIの提案",
155	        text: raw.text ?? "",
156	        ref: raw.ref,
157	      });
158	    }
159	  }
160	
161	  return { body, suggestions };
162	}
