1	"use client";
2	
3	import "quill/dist/quill.bubble.css";
4	import type Quill from "quill";
5	import {
6	  forwardRef,
7	  useEffect,
8	  useImperativeHandle,
9	  useMemo,
10	  useRef,
11	  useState,
12	} from "react";
13	import { api } from "@/lib/api";
14	import type { Item } from "@/lib/types";
15	import type { DeltaOp } from "@/lib/note-delta";
16	import { Icon } from "./icon";
17	
18	export type CiteTarget = { title: string; site: string; url: string };
19	export type NoteEditorHandle = { insertTextAtCursor: (text: string) => void };
20	
21	/** An `@token` at the caret — after a space or line start, so `foo@bar.com`
22	 *  and `@decorator` mid-word don't trigger it. */
23	const TRIGGER = /(?:^|\s)@([^\s@[\]]*)$/;
24	
25	const TOOLBAR = [
26	  ["bold", "italic"],
27	  [{ header: 2 }, { header: 3 }],
28	  ["blockquote", "link"],
29	  [{ list: "bullet" }, { list: "ordered" }],
30	];
31	
32	type MentionState = {
33	  /** doc index of the trigger `@`. */
34	  at: number;
35	  /** chars to replace (the `@` + query). */
36	  len: number;
37	  query: string;
38	  top: number;
39	  left: number;
40	};
41	
42	function iconFor(kind: Item["kind"]): string {
43	  return kind === "video"
44	    ? "play-circle"
45	    : kind === "pdf"
46	      ? "file-pdf"
47	      : kind === "thread"
48	        ? "chats"
49	        : "globe";
50	}
51	
52	/**
53	 * The Quill (bubble theme) note body. Round-trips the Delta `ops` array, emits
54	 * a debounced `onChange`, and pops a saved-URL picker when you type `@` — the
55	 * pick inserts a link and calls `onCite` so the note records it as a source.
56	 */
57	export const NoteEditor = forwardRef<
58	  NoteEditorHandle,
59	  {
60	    value: DeltaOp[];
61	    onChange: (ops: DeltaOp[]) => void;
62	    onCite: (target: CiteTarget) => void;
63	    placeholder?: string;
64	  }
65	>(function NoteEditor({ value, onChange, onCite, placeholder }, ref) {
66	  const holderRef = useRef<HTMLDivElement>(null);
67	  const quillRef = useRef<Quill | null>(null);
68	  const onChangeRef = useRef(onChange);
69	  const onCiteRef = useRef(onCite);
70	  onChangeRef.current = onChange;
71	  onCiteRef.current = onCite;
72	
73	  const [items, setItems] = useState<Item[]>([]);
74	  const [mention, setMention] = useState<MentionState | null>(null);
75	  const [sel, setSel] = useState(0);
76	  const mentionRef = useRef<MentionState | null>(null);
77	  const selRef = useRef(sel);
78	  mentionRef.current = mention;
79	  selRef.current = sel;
80	
81	  useEffect(() => {
82	    api
83	      .items()
84	      .then((its) => setItems(its.filter((it) => it.kind !== "note")))
85	      .catch(() => {});
86	  }, []);
87	
88	  const results = useMemo(() => {
89	    if (!mention) return [];
90	    const q = mention.query.toLowerCase();
91	    return items
92	      .filter((it) => !q || `${it.title} ${it.site} ${it.url}`.toLowerCase().includes(q))
93	      .slice(0, 8);
94	  }, [items, mention]);
95	  const resultsRef = useRef(results);
96	  resultsRef.current = results;
97	
98	  // ── mount Quill (dynamic import — Quill touches `document` at load) ──
99	  useEffect(() => {
100	    let quill: Quill | null = null;
101	    let debounce: ReturnType<typeof setTimeout> | null = null;
102	    let disposed = false;
103	
104	    (async () => {
105	      const { default: QuillCtor } = await import("quill");
106	      if (disposed || !holderRef.current) return;
107	
108	      quill = new QuillCtor(holderRef.current, {
109	        theme: "bubble",
110	        placeholder,
111	        modules: { toolbar: TOOLBAR },
112	      });
113	      quillRef.current = quill;
114	      if (value.length) quill.setContents({ ops: value } as never, "silent");
115	
116	      const scan = () => {
117	        const range = quill?.getSelection();
118	        if (!quill || !range || range.length > 0) return setMention(null);
119	        const before = quill.getText(0, range.index);
120	        const m = before.match(TRIGGER);
121	        if (!m) return setMention(null);
122	        const at = range.index - m[0].length + m[0].indexOf("@");
123	        const b = quill.getBounds(range.index) ?? { top: 0, left: 0, height: 20 };
124	        setSel(0);
125	        setMention({ at, len: range.index - at, query: m[1], top: b.top + b.height + 4, left: b.left });
126	      };
127	
128	      quill.on("text-change", (_d, _o, source) => {
129	        scan();
130	        if (source !== "user") return;
131	        if (debounce) clearTimeout(debounce);
132	        debounce = setTimeout(() => {
133	          onChangeRef.current(quill?.getContents().ops ?? []);
134	        }, 600);
135	      });
136	      quill.on("selection-change", scan);
137	
138	      quill.root.addEventListener("keydown", onKeyDown, true);
139	    })();
140	
141	    function onKeyDown(e: KeyboardEvent) {
142	      const men = mentionRef.current;
143	      const res = resultsRef.current;
144	      if (!men || res.length === 0) return;
145	      if (e.key === "ArrowDown") {
146	        e.preventDefault();
147	        setSel((s) => (s + 1) % res.length);
148	      } else if (e.key === "ArrowUp") {
149	        e.preventDefault();
150	        setSel((s) => (s - 1 + res.length) % res.length);
151	      } else if (e.key === "Enter" || e.key === "Tab") {
152	        e.preventDefault();
153	        pick(res[selRef.current] ?? res[0]);
154	      } else if (e.key === "Escape") {
155	        e.preventDefault();
156	        setMention(null);
157	      }
158	    }
159	
160	    return () => {
161	      disposed = true;
162	      if (debounce) clearTimeout(debounce);
163	      quill?.root.removeEventListener("keydown", onKeyDown, true);
164	      // flush a pending edit
165	      const q = quillRef.current;
166	      if (q) onChangeRef.current(q.getContents().ops ?? []);
167	      quillRef.current = null;
168	    };
169	    // biome-ignore lint/correctness/useExhaustiveDependencies: mount-once; refs carry live props
170	  }, []);
171	
172	  function pick(it: Item | undefined) {
173	    const q = quillRef.current;
174	    const men = mentionRef.current;
175	    if (!q || !it || !men) return;
176	    q.deleteText(men.at, men.len, "user");
177	    q.insertText(men.at, it.title, { link: it.url }, "user");
178	    q.insertText(men.at + it.title.length, " ", {}, "user");
179	    q.setSelection(men.at + it.title.length + 1, 0, "user");
180	    onCiteRef.current({ title: it.title, site: it.site, url: it.url });
181	    setMention(null);
182	    onChangeRef.current(q.getContents().ops ?? []);
183	  }
184	
185	  useImperativeHandle(ref, () => ({
186	    insertTextAtCursor(text: string) {
187	      const q = quillRef.current;
188	      if (!q) return;
189	      const range = q.getSelection(true);
190	      const idx = range ? range.index : q.getLength();
191	      q.insertText(idx, `${text}\n`, "user");
192	      q.setSelection(idx + text.length + 1, 0, "user");
193	      onChangeRef.current(q.getContents().ops ?? []);
194	    },
195	  }));
196	
197	  return (
198	    <div className="note-editor relative">
199	      <div ref={holderRef} />
200	      {mention && results.length > 0 && (
201	        <ul
202	          className="absolute z-20 max-h-[240px] w-[min(440px,90vw)] overflow-auto rounded-lg bg-neutral-900 py-1 shadow-[0_0_0_1px_var(--color-neutral-800),0_14px_36px_rgba(0,0,0,0.5)]"
203	          style={{ top: mention.top, left: mention.left }}
204	        >
205	          {results.map((it, i) => (
206	            <li key={it.id}>
207	              <button
208	                type="button"
209	                onMouseDown={(e) => {
210	                  e.preventDefault();
211	                  pick(it);
212	                }}
213	                className={`flex w-full items-start gap-[9px] px-[11px] py-[8px] text-left ${
214	                  i === sel ? "bg-accent/[0.16]" : "hover:bg-white/[0.05]"
215	                }`}
216	              >
217	                <Icon name={iconFor(it.kind)} size={14} className="mt-[2px] text-accent" />
218	                <span className="min-w-0 flex-1">
219	                  <span className="block truncate text-[13px] text-text">{it.title}</span>
220	                  <span className="block truncate text-[11px] text-text/50">{it.site}</span>
221	                </span>
222	              </button>
223	            </li>
224	          ))}
225	        </ul>
226	      )}
227	    </div>
228	  );
229	});
