1	import { type NextRequest, NextResponse } from "next/server";
2	import { requireAppUser } from "@/lib/db/current-user";
3	import { acceptSuggestion, dismissSuggestion } from "@/lib/db/repo";
4	
5	export const dynamic = "force-dynamic";
6	
7	type Ctx = { params: Promise<{ id: string }> };
8	
9	/** body: { id: string, action: "accept" | "dismiss" } */
10	export async function POST(req: NextRequest, { params }: Ctx) {
11	  const user = await requireAppUser();
12	  const { id } = await params;
13	  const body = await req.json().catch(() => ({}));
14	  const suggestionId = typeof body.id === "string" ? body.id : "";
15	  const action = body.action;
16	  if (!suggestionId || (action !== "accept" && action !== "dismiss")) {
17	    return NextResponse.json({ error: "bad request" }, { status: 400 });
18	  }
19	  const note =
20	    action === "accept"
21	      ? await acceptSuggestion(user.id, id, suggestionId)
22	      : await dismissSuggestion(user.id, id, suggestionId);
23	  if (!note) return NextResponse.json({ error: "not found" }, { status: 404 });
24	  return NextResponse.json(note);
25	}
