38	const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
39	/** Guard lookups: an empty or malformed id must not reach Postgres as a
40	 * `::uuid` cast (it throws instead of returning no rows). */
41	const isUuid = (id: string): boolean => UUID_RE.test(id);
42	
43	function relativeLabel(when: Date | string): string {
44	  const min = Math.floor((Date.now() - new Date(when).getTime()) / 60_000);
45	  if (min < 1) return "たった今";
46	  if (min < 60) return `${min}分前`;
47	  const hours = Math.floor(min / 60);
48	  if (hours < 24) return "今日";
49	  const days = Math.floor(hours / 24);
50	  return days === 1 ? "昨日" : `${days}日前`;
51	}
52	
53	function kindFromUrl(url: string): SourceKind {
54	  const u = url.toLowerCase();
55	  if (u.includes("youtube") || u.includes("youtu.be") || u.includes("vimeo")) return "video";
56	  if (u.endsWith(".pdf") || u.includes("arxiv.org")) return "pdf";
57	  if (u.includes("twitter.com") || u.includes("x.com") || u.includes("bsky")) return "thread";
58	  return "article";
59	}
60	
61	function siteFromUrl(url: string): string {
62	  try {
63	    return new URL(url).hostname.replace(/^www\./, "");
64	  } catch {
65	    return url.slice(0, 40);
66	  }
67	}
68	
69	function normalizeUrl(url: string): string {
70	  try {
71	    const u = new URL(url);
72	    return `${u.hostname.replace(/^www\./, "")}${u.pathname.replace(/\/+$/, "")}${u.search}`.toLowerCase();
73	  } catch {
74	    return url.trim().toLowerCase();
75	  }
76	}
