78	// ── Items ──────────────────────────────────────────────────
79	type SavedUrlRow = typeof schema.savedUrls.$inferSelect;
80	
81	function toItem(row: SavedUrlRow): Item {
82	  const site = row.kind === "note" ? (row.domain ?? "メモ") : (row.domain ?? siteFromUrl(row.url));
83	  return {
84	    id: row.id,
85	    url: row.url,
86	    kind: row.kind as SourceKind,
87	    site,
88	    title: row.title ?? site,
89	    addedAt: new Date(row.createdAt).toISOString(),
90	    addedLabel: relativeLabel(row.createdAt),
91	    status:
92	      row.fetchStatus === "success" ? "ready" : row.fetchStatus === "error" ? "ready" : "reading",
93	    durationLabel: row.durationLabel ?? undefined,
94	    summary: row.summaryLines,
95	    points: row.points,
96	    suggestedTags: row.suggestedTags,
97	    tags: row.tags,
98	    projectId: row.projectId ?? null,
99	    quoteCandidates: row.quoteCandidates,
100	    relatedNoteId: row.relatedNoteId ?? undefined,
101	  };
102	}
