104	export async function listItems(userId: string): Promise<Item[]> {
105	  const rows = await db.query.savedUrls.findMany({
106	    where: (t, { eq }) => eq(t.userId, userId),
107	    orderBy: (t, { desc }) => [desc(t.createdAt)],
108	  });
109	  return rows.map(toItem);
110	}
