112	/**
113	 * GET /api/items/importable — the "Hazyから追加" picker in the capture flow.
114	 * Every URL the user has in the hazy database (the `saved_urls` table this
115	 * app is connected to), newest first, so they can pull one into the note
116	 * pipeline (`/capture?id=…` → finishReading → 要約とタグ → 置き場所).
117	 *
118	 * Pasted memos (`kind: "note"`) are excluded — this is for real URLs. Items
119	 * hazy-note has already worked on (summary generated, or filed into a
120	 * project) are still listed; the picker marks them so and selecting one just
121	 * re-opens it. Unworked items sort to the top.
122	 */
123	export async function listImportable(userId: string): Promise<Item[]> {
124	  const rows = await db.query.savedUrls.findMany({
125	    where: (t, { and, eq, ne }) => and(eq(t.userId, userId), ne(t.kind, "note")),
126	    orderBy: (t, { desc }) => [desc(t.createdAt)],
127	  });
128	  const items = rows.map(toItem);
129	  const worked = (it: Item) => it.summary.length > 0 || it.projectId !== null;
130	  return [...items.filter((it) => !worked(it)), ...items.filter(worked)];
131	}
132	
133	export async function getItem(userId: string, id: string): Promise<Item | undefined> {
134	  if (!isUuid(id)) return undefined;
135	  const row = await db.query.savedUrls.findFirst({
136	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
137	  });
138	  return row ? toItem(row) : undefined;
139	}
