141	export async function addItem(userId: string, url: string): Promise<Item> {
142	  const site = siteFromUrl(url);
143	  const [row] = await db
144	    .insert(schema.savedUrls)
145	    .values({
146	      userId,
147	      url,
148	      normalizedUrl: normalizeUrl(url),
149	      domain: site,
150	      title: site,
151	      kind: kindFromUrl(url),
152	      fetchStatus: "pending",
153	    })
154	    .onConflictDoUpdate({
155	      target: [schema.savedUrls.userId, schema.savedUrls.normalizedUrl],
156	      set: { fetchStatus: "pending", updatedAt: new Date() },
157	    })
158	    .returning();
159	  const item = await getItem(userId, row.id);
160	  if (!item) throw new Error("item vanished immediately after write");
161	  return item;
162	}
