164	/**
165	 * POST /api/items — the memo path. A pasted memo becomes an item with no
166	 * external URL; `kind: "note"` and the raw text lives in `extracted_text`.
167	 */
168	export async function addMemo(userId: string, text: string): Promise<Item> {
169	  const token = `hazy:memo:${crypto.randomUUID()}`;
170	  const firstLine = text.trim().split("\n")[0].trim();
171	  const title = firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine || "メモ";
172	  const [row] = await db
173	    .insert(schema.savedUrls)
174	    .values({
175	      userId,
176	      url: token,
177	      normalizedUrl: token,
178	      domain: "メモ",
179	      title,
180	      kind: "note",
181	      extractedText: text,
182	      fetchStatus: "pending",
183	    })
184	    .returning();
185	  const item = await getItem(userId, row.id);
186	  if (!item) throw new Error("item vanished immediately after write");
187	  return item;
188	}
