190	/**
191	 * POST /api/items/:id/read — the "読み取り" step. For a URL this fetches the
192	 * page, extracts its text, and asks the model for a summary + tags. For a
193	 * pasted memo it just distils what was written. Best-effort: a fetch or AI
194	 * failure still resolves the item (fetch_status "error") instead of throwing.
195	 *
196	 * "Hazyから追加" fast path: an item saved via the hazy app already has its
197	 * page text in `extracted_text`. If it's substantial, summarise straight from
198	 * that — no second network fetch, and a transient fetch failure can't downgrade
199	 * an item hazy already read successfully.
200	 */
201	export async function finishReading(userId: string, id: string): Promise<Item | undefined> {
202	  const existing = await db.query.savedUrls.findFirst({
203	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
204	  });
205	  if (!existing) return undefined;
206	
207	  if (existing.kind !== "note" && (existing.extractedText?.trim().length ?? 0) >= 400) {
208	    const title =
209	      existing.title && existing.title !== existing.domain
210	        ? existing.title
211	        : (existing.domain ?? siteFromUrl(existing.url));
212	    const digest = await summariseSource({
213	      title,
214	      text: existing.extractedText ?? "",
215	      kind: existing.kind,
216	    });
217	    await db
218	      .update(schema.savedUrls)
219	      .set({
220	        fetchStatus: "success",
221	        title: digest.title?.trim() || title,
222	        durationLabel:
223	          existing.durationLabel ??
224	          (existing.estimatedReadMinutes ? `読了${existing.estimatedReadMinutes}分` : null),
225	        summaryLines: digest.summary,
226	        points: digest.points,
227	        suggestedTags: digest.suggestedTags,
228	        updatedAt: new Date(),
229	      })
230	      .where(eq(schema.savedUrls.id, id));
231	    return getItem(userId, id);
232	  }
233	
234	  if (existing.kind === "note") {
235	    const digest = await summariseMemo(existing.extractedText ?? "");
236	    await db
237	      .update(schema.savedUrls)
238	      .set({
239	        fetchStatus: "success",
240	        summaryLines: digest.summary,
241	        points: digest.points,
242	        suggestedTags: digest.suggestedTags,
243	        updatedAt: new Date(),
244	      })
245	      .where(eq(schema.savedUrls.id, id));
246	    return getItem(userId, id);
247	  }
248	
249	  let extracted: Awaited<ReturnType<typeof fetchAndExtract>>;
250	  try {
251	    extracted = await fetchAndExtract(existing.url);
252	  } catch (e) {
253	    await db
254	      .update(schema.savedUrls)
255	      .set({
256	        fetchStatus: "error",
257	        fetchError: (e as Error).message.slice(0, 500),
258	        updatedAt: new Date(),
259	      })
260	      .where(eq(schema.savedUrls.id, id));
261	    return getItem(userId, id);
262	  }
263	
264	  const title =
265	    extracted.title?.trim() ||
266	    (existing.title && existing.title !== existing.domain
267	      ? existing.title
268	      : (existing.domain ?? siteFromUrl(existing.url)));
269	
270	  const digest = await summariseSource({
271	    title,
272	    text: extracted.text,
273	    kind: existing.kind,
274	  });
275	
276	  await db
277	    .update(schema.savedUrls)
278	    .set({
