467	function toNote(row: typeof schema.notes.$inferSelect): Note {
468	  // Notes written before the Quill editor only have `blocks`; convert on read
469	  // (persisted back to `body` / `suggestions` on the next save).
470	  const rowBody = row.body as DeltaOp[];
471	  const rowSug = row.suggestions as NoteSuggestion[];
472	  const hasBody = isDelta(rowBody) && rowBody.length > 0;
473	  const hasSug = rowSug.length > 0;
474	  const legacy = hasBody && hasSug ? null : legacyBlocksToDelta(row.blocks);
475	  return {
476	    id: row.id,
477	    title: row.title,
478	    projectId: row.projectId ?? "",
479	    tags: row.tags as Note["tags"],
480	    status: row.status,
481	    updatedLabel: `自動保存 · ${relativeLabel(row.updatedAt)}`,
482	    body: hasBody ? rowBody : (legacy?.body ?? []),
483	    suggestions: hasSug ? rowSug : (legacy?.suggestions ?? []),
484	    sources: row.sources as Note["sources"],
485	    links: row.links as Note["links"],
486	    flags: row.flags as Note["flags"],
487	  };
488	}
