707	export async function buildExport(
708	  userId: string,
709	  noteId: string,
710	  format: ExportFormat = "blog"
711	): Promise<ExportDraft> {
712	  let note = await getNote(userId, noteId);
713	  if (!note) {
714	    const fallback = await db.query.notes.findFirst({
715	      where: (t, { eq }) => eq(t.userId, userId),
716	      orderBy: (t, { desc }) => [desc(t.updatedAt)],
717	    });
718	    note = fallback ? toNote(fallback) : undefined;
719	  }
720	  if (!note) {
721	    return {
722	      format,
723	      meta: "ノートがありません",
724	      title: "書き出すノートがありません",
725	      blocks: [{ type: "p", text: "先にノートを作成してください。" }],
726	      provenance: [],
727	    };
728	  }
729	
730	  const draft = await rewriteForExport({
731	    title: note.title,
732	    markdown: deltaToMarkdown(note.body),
733	    format,
734	  });
735	  const chars = countChars(draft.blocks);
736	  const minutes = Math.max(1, Math.round(chars / 500));
737	  const meta =
738	    format === "bullets"
739	      ? `${draft.blocks.filter((b) => b.type === "p").length}項目`
740	      : `約${chars.toLocaleString()}字 · 読了${minutes}分`;
741	
742	  return { format, meta, ...draft };
743	}
