5	class MarkdownActivity {
6	  constructor (quillJS, options = {}) {
7	    this.quillJS = quillJS
8	    this.options = options
9	    this.onTextChangeBound = this.onTextChange.bind(this)
10	    this.quillJS.on('text-change', this.onTextChangeBound)
11	    this.actionCharacters = {
12	      whiteSpace: ' ',
13	      newLine: '\n',
14	      asterisk: '*',
15	      rightParenthesis: ')',
16	      grave: '`',
17	      tilde: '~',
18	      underscore: '_'
19	    }
20	    this.ignoreTags = ['PRE', ...(options.ignoreTags || [])]
21	    this.tags = new TagsOperators(this.quillJS, options)
22	    this.matches = this.tags.getOperatorsAll()
23	    this.fullMatches = this.tags.getFullTextOperatorsAll()
24	  }
25	
26	  destroy () {
27	    this.quillJS.off('text-change', this.onTextChangeBound)
28	  }
29	
30	  onTextChange (delta, oldContents, source) {
31	    if (source !== 'user') return
32	    const cursorOffset = (delta.ops[0] && delta.ops[0].retain) || 0
33	    const inputText = delta.ops[0].insert || (delta.ops[1] && delta.ops[1].insert)
34	    const [removeLine] = this.quillJS.getLine(cursorOffset)
35	    const insertDelta = delta.ops.find(e => e.hasOwnProperty('insert')) || {}
36	    const isRemoveCommand = delta.ops.find(e => e.hasOwnProperty('delete')) || insertDelta.insert === '\n'
37	    if (isRemoveCommand && removeLine.domNode.textContent.length <= 1) {
38	      const rangeElements = ['PRE', 'BLOCKQUOTE']
39	      if (rangeElements.includes(removeLine.domNode.tagName)) {
40	        this.onRemoveElement({ delete: 1 })
41	      }
42	    }
43	
44	    if (!inputText) return
45	    if (inputText.length > 1) {
46	      setTimeout(async () => {
47	        const cursorOffsetFixed = cursorOffset
48	        const tokens = inputText.split('\n')
49	        let _offset = cursorOffsetFixed
50	        // eslint-disable-next-line no-unused-vars
51	        for (let v of tokens) {
52	          const [line] = this.quillJS.getLine(_offset)
53	          if (!line) {
54	            return 0
55	          }
56	          const firstIndex = this.quillJS.getIndex(line)
57	          let _targetText = ''
58	          let result = await this.onFullTextExecute.bind(this)({ index: firstIndex, delta, length: 0 })
59	
60	          if (result) {
61	            while (result) {
62	              const [line] = this.quillJS.getLine(_offset)
63	              const firstIndex = this.quillJS.getIndex(line)
64	              if (!line || !(line.domNode)) {
65	                result = false
66	                break
67	              }
68	
69	              _targetText = line.domNode.textContent || ''
70	              result = await this.onFullTextExecute.bind(this)({ index: firstIndex, delta, length: 0 })
71	            }
72	          } else {
73	            _targetText = line.domNode.textContent || ''
74	          }
75	          _offset += _targetText.length + 1
76	        }
77	      }, 0)
78	      return
79	    }
80	
81	    delta.ops.filter(e => e.hasOwnProperty('insert')).forEach(e => {
82	      switch (e.insert) {
83	        case this.actionCharacters.whiteSpace:
84	        case this.actionCharacters.rightParenthesis:
85	        case this.actionCharacters.asterisk:
86	        case this.actionCharacters.grave:
87	        case this.actionCharacters.newLine:
88	        case this.actionCharacters.tilde:
89	        case this.actionCharacters.underscore:
90	          this.onInlineExecute.bind(this)()
91	          break
92	      }
93	    })
94	
95	    delta.ops.filter(e => e.hasOwnProperty('delete')).forEach((e) => {
96	      this.onRemoveElement(e)
97	    })
98	  }
99	
100	  onInlineExecute () {
101	    const selection = this.quillJS.getSelection()
102	    if (!selection) return
103	    const [line, offset] = this.quillJS.getLine(selection.index)
104	    const text = line.domNode.textContent
105	    const lineStart = selection.index - offset
106	    const format = this.quillJS.getFormat(lineStart)
107	    if (format['code-block'] || format['code']) {
108	      // if exists text in code-block, to skip.
109	      return
110	    }
111	    for (let match of this.matches) {
112	      const matchedText = typeof match.pattern === 'function' ? match.pattern(text) : text.match(match.pattern)
113	      if (matchedText) {
114	        match.action(text, selection, match.pattern, lineStart)
115	        return
116	      }
117	    }
118	  }
119	
120	  async onFullTextExecute (virtualSelection) {
121	    let selection = virtualSelection || this.quillJS.getSelection()
122	    const delta = virtualSelection.delta
123	    if (!selection) return false
124	    const [line, offset] = this.quillJS.getLine(selection.index)
125	
126	    if (!line || offset < 0) return false
127	    const retain = (delta && delta.ops && delta.ops[0].retain) || 0
128	    const lineStart = selection.index - offset
129	    const formatLineStart = retain ? retain - 1 : lineStart
130	    const format = this.quillJS.getFormat(formatLineStart)
131	    if (format['code-block'] || format['code']) {
132	      // if exists text in code-block, to skip.
133	
134	      if (format['code']) {
135	        // ignore all styles when copied text in code block.
136	        const copiedTexts = delta.ops.filter(d => d.insert).map(d => d.insert).join('')
137	        this.quillJS.deleteText(retain, copiedTexts.length)
138	        this.quillJS.insertText(retain, copiedTexts.replace(/\n/g, ''), { code: true })
139	        this.quillJS.format('code', false)
140	      }
141	      return false
142	    }
143	    const beforeNode = this.quillJS.getLine(lineStart - 1)[0]
144	    const beforeLineText = beforeNode && beforeNode.domNode.textContent
145	    const text = line.domNode.textContent + ' '
146	    selection.length = selection.index++
147	    // remove block rule.
148	    if (typeof beforeLineText === 'string' && beforeLineText.length > 0 && text === ' ') {
149	      const releaseTag = this.fullMatches.find(e => e.name === line.domNode.tagName.toLowerCase())
150	      if (releaseTag && releaseTag.release) {
151	        releaseTag.release(selection)
152	        return false
153	      }
154	    }
155	
156	    for (let match of this.fullMatches) {
157	      const matchedText = typeof match.pattern === 'function' ? match.pattern(text) : text.match(match.pattern)
158	      if (matchedText) {
159	        // eslint-disable-next-line no-return-await
160	        return await match.action(text, selection, match.pattern, lineStart)
161	      }
162	    }
163	    return false
164	  }
165	
166	  onRemoveElement (range) {
167	    const selection = this.quillJS.getSelection()
168	    // if removed one item before, editor need to clear item.
169	    if (range && range.delete === 1) {
170	      const removeItem = this.quillJS.getLine(selection.index)
171	      const lineItem = removeItem[0]
172	      const releaseTag = this.matches.find(e => e.name === lineItem.domNode.tagName.toLowerCase())
173	      if (releaseTag && releaseTag.release) {
174	        releaseTag.release(selection)
175	      }
176	    }
177	  }
178	}
